const NetworkAnalyzer = require('../../lib/dependency-graph/simulator/network-analyzer.js');
const NetworkRecorder = require('../../lib/network-recorder.js');

function simulateNetworkRequest() {
  const records = [
    {
      url: 'data:image/png;base64,',
      startTime: 0,
      endTime: 1,
      transferSize: 208,
      resourceType: 'Image',
      protocol: 'data',
      finished: true,
    },
  ];

  const additionalRttByOrigin = new Map();
  const serverResponseTimeByOrigin = new Map();

  const recordsByOrigin = NetworkAnalyzer.groupByOrigin(records);
  for (const [origin, records] of recordsByOrigin.entries()) {
    const additionalRtt = additionalRttByOrigin.get(origin) || 0;
    const responseTime = serverResponseTimeByOrigin.get(origin) || 0;
    console.log('RTT & server response', origin, additionalRtt, responseTime);
  }
}

simulateNetworkRequest();
